using System.Collections.Generic;
using UnityEngine;

namespace Komikan
{
    /// <summary>
    /// The single component the scene needs. On Start it builds the whole game
    /// in code: the board graph, the board renderer, the Pangui piece view and
    /// the 12 Trewa piece views (sprites generated by <see cref="SpriteFactory"/>),
    /// the <see cref="GameManager"/>, the <see cref="HumanInputController"/>, the
    /// easy <see cref="TrewasAI"/> and the <see cref="UIController"/>, wiring every
    /// reference so no manual Inspector setup is required.
    /// </summary>
    public class GameBootstrap : MonoBehaviour
    {
        [Tooltip("World-space distance between adjacent board nodes.")]
        public float Spacing = 1.4f;

        [Tooltip("Optional fixed seed for the AI; 0 means use a time-based seed.")]
        public int AiSeed = 0;

        private void Start()
        {
            EnsureCamera();

            var board = new BoardGraph();

            // Board renderer.
            var rendererGO = new GameObject("BoardRenderer");
            rendererGO.transform.SetParent(transform, false);
            var renderer = rendererGO.AddComponent<BoardRenderer>();
            renderer.Spacing = Spacing;
            renderer.Build(board);

            // Sprites (generated in code).
            Sprite panguiSprite = SpriteFactory.CreateCircleSprite(SpriteFactory.PanguiColor, 128, 128f);
            Sprite trewaSprite = SpriteFactory.CreateCircleSprite(SpriteFactory.TrewaColor, 128, 128f);

            float pieceScale = Spacing * 0.42f;

            // Pangui piece view.
            PieceView panguiView = CreatePieceView("Pangui", panguiSprite, SpriteFactory.PanguiColor, 3, pieceScale);

            // 12 Trewa piece views.
            var trewaViews = new List<PieceView>(12);
            for (int i = 0; i < 12; i++)
            {
                PieceView view = CreatePieceView($"Trewa_{i}", trewaSprite, SpriteFactory.TrewaColor, 2, pieceScale);
                trewaViews.Add(view);
            }

            // AI.
            TrewasAI ai = AiSeed != 0 ? new TrewasAI(AiSeed) : new TrewasAI();

            // Game manager.
            var managerGO = new GameObject("GameManager");
            managerGO.transform.SetParent(transform, false);
            var manager = managerGO.AddComponent<GameManager>();
            manager.Configure(board, renderer, panguiView, trewaViews, ai);

            // Human input.
            var inputGO = new GameObject("HumanInputController");
            inputGO.transform.SetParent(transform, false);
            var input = inputGO.AddComponent<HumanInputController>();
            input.ClickRadius = Spacing * 0.45f;
            input.Configure(manager, board, Camera.main);

            // UI.
            var uiGO = new GameObject("UIController");
            uiGO.transform.SetParent(transform, false);
            var ui = uiGO.AddComponent<UIController>();
            ui.Configure(manager);

            // Kick off the first game.
            manager.StartNewGame();
        }

        private PieceView CreatePieceView(string objName, Sprite sprite, Color color, int sortingOrder, float scale)
        {
            var go = new GameObject(objName);
            go.transform.SetParent(transform, false);
            var view = go.AddComponent<PieceView>();
            view.Initialize(sprite, color, sortingOrder, Vector3.one * scale);
            return view;
        }

        private void EnsureCamera()
        {
            Camera cam = Camera.main;
            if (cam == null)
            {
                var camGO = new GameObject("Main Camera");
                camGO.tag = "MainCamera";
                cam = camGO.AddComponent<Camera>();
            }

            cam.orthographic = true;
            cam.orthographicSize = Spacing * 4.5f;
            cam.transform.position = new Vector3(0f, 0f, -10f);
            cam.backgroundColor = new Color(0.12f, 0.12f, 0.16f, 1f);
            cam.clearFlags = CameraClearFlags.SolidColor;
        }
    }
}
